<?php
namespace App\Services;
use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class ImageProcessor {public function store(UploadedFile $file,string $folder='cms',int $maxWidth=1920):string{$info=getimagesize($file->getRealPath());$source=match($info[2]??null){IMAGETYPE_JPEG=>imagecreatefromjpeg($file->getRealPath()),IMAGETYPE_PNG=>imagecreatefrompng($file->getRealPath()),IMAGETYPE_WEBP=>imagecreatefromwebp($file->getRealPath()),default=>null};if(!$source)return $file->store($folder,'public');$width=imagesx($source);$height=imagesy($source);$targetWidth=min($width,$maxWidth);$targetHeight=(int)round($height*$targetWidth/$width);$target=imagecreatetruecolor($targetWidth,$targetHeight);imagealphablending($target,false);imagesavealpha($target,true);imagecopyresampled($target,$source,0,0,0,0,$targetWidth,$targetHeight,$width,$height);$path=$folder.'/'.Str::uuid().'.webp';ob_start();imagewebp($target,null,82);Storage::disk('public')->put($path,ob_get_clean());imagedestroy($source);imagedestroy($target);return $path;}}
